import re
from datetime import datetime, timezone
from typing import List, Optional, Literal, Dict, Any
from pydantic import BaseModel, Field, field_validator


class InterviewQuestionSchema(BaseModel):
    """Core schema for interview questions generated by Gemini or served by fallback bank."""
    question: str = Field(..., min_length=5, description="The interview question text.")
    intent: str = Field(..., description="The underlying competency, skill, or architectural principle being tested.")
    difficulty: Literal["easy", "medium", "hard"] = Field(
        "medium",
        description="Difficulty tier: 'easy' | 'medium' | 'hard'"
    )
    expected_points: List[str] = Field(
        default_factory=list,
        description="Key criteria or points expected in a strong candidate answer."
    )

    @field_validator("difficulty", mode="before")
    @classmethod
    def normalize_difficulty(cls, v: Any) -> str:
        if isinstance(v, str):
            clean = v.strip().lower()
            if clean in ("easy", "medium", "hard"):
                return clean
        return "medium"


class LabeledQuestion(InterviewQuestionSchema):
    """Interview question clearly labeled with its provenance and fallback status."""
    source: Literal["gemini", "offline_bank"] = Field(
        ...,
        description="Origin source: 'gemini' for live AI generation, or 'offline_bank' for offline fallback."
    )
    is_fallback: bool = Field(
        False,
        description="Explicit flag indicating if content was served from offline fallback bank. Never disguised as AI."
    )
    round_type: str = Field(
        "hr",
        description="Interview round type: 'hr' or 'technical'."
    )
    category: Optional[str] = Field(
        None,
        description="Sub-domain or behavioral category (e.g., 'Crisis Management', 'System Design')."
    )
    is_follow_up: bool = Field(
        False,
        description="Indicates whether this question is an adaptive follow-up."
    )
    parent_question: Optional[str] = Field(
        None,
        description="Reference text of the parent question if this is a follow-up."
    )


class ConversationTurn(BaseModel):
    """Represents a single conversational turn in the interview memory."""
    role: Literal["interviewer", "candidate"] = Field(..., description="'interviewer' or 'candidate'")
    content: str = Field(..., description="Cleaned dialogue content (speech).")
    raw_content: Optional[str] = Field(None, description="Raw STT transcript prior to echo-stripping.")
    timestamp: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))
    metadata: Dict[str, Any] = Field(default_factory=dict)


class SessionState(BaseModel):
    """In-memory session state maintained per interview session."""
    session_id: str
    round_type: str = "hr"
    domain: str = "General"
    current_difficulty: Literal["easy", "medium", "hard"] = "medium"
    current_question_index: int = 0
    total_questions: int = 5
    is_completed: bool = False
    consecutive_follow_ups: int = 0
    current_question: Optional[LabeledQuestion] = None
    history: List[ConversationTurn] = Field(default_factory=list)


class CoordinatorTurnResult(BaseModel):
    """Result returned by Coordinator for each processed candidate turn or turn advancement."""
    session_id: str
    next_action: Literal["next_question", "follow_up", "completed"]
    question: Optional[LabeledQuestion] = None
    current_difficulty: str
    round_type: str
    turn_index: int
    total_questions: int
    cleaned_transcript: Optional[str] = None
    evaluation: Optional[Dict[str, Any]] = None


# =====================================================================
# QUIZ & MCQ SCHEMAS
# =====================================================================

class QuizQuestionSchema(BaseModel):
    """Schema for Quiz & Multiple Choice Questions (MCQ)."""
    stem: str = Field(..., min_length=5, description="The question statement or problem prompt.")
    options: List[str] = Field(..., description="Exactly 4 unique option choices.")
    correct_index: int = Field(..., description="0-based index of the correct answer (0 <= correct_index < 4).")
    explanation: str = Field(..., min_length=5, description="Detailed explanation of why the correct option is right.")
    topic: str = Field(..., description="Subject or domain topic (e.g., 'Quantitative Aptitude', 'Python').")
    difficulty: Literal["easy", "medium", "hard"] = Field(
        "medium",
        description="Difficulty tier: 'easy' | 'medium' | 'hard'"
    )

    @field_validator("difficulty", mode="before")
    @classmethod
    def normalize_difficulty(cls, v: Any) -> str:
        if isinstance(v, str):
            clean = v.strip().lower()
            if clean in ("easy", "medium", "hard"):
                return clean
        return "medium"

    @field_validator("options")
    @classmethod
    def validate_options(cls, v: List[str]) -> List[str]:
        if not isinstance(v, list) or len(v) != 4:
            raise ValueError(f"options must contain exactly 4 choices, got {len(v) if isinstance(v, list) else type(v)}")
        cleaned = [str(opt).strip() for opt in v]
        if any(not opt for opt in cleaned):
            raise ValueError("All options must be non-empty strings")
        unique_opts = set(opt.lower() for opt in cleaned)
        if len(unique_opts) != len(cleaned):
            raise ValueError("All 4 options must be unique; duplicates detected")
        return cleaned

    @field_validator("correct_index")
    @classmethod
    def validate_correct_index(cls, v: int) -> int:
        if not isinstance(v, int) or v < 0 or v >= 4:
            raise ValueError(f"correct_index must be an integer satisfying 0 <= correct_index < 4, got {v}")
        return v


class LabeledQuizQuestion(QuizQuestionSchema):
    """Quiz question clearly labeled with provenance and fallback status."""
    source: Literal["gemini", "offline_bank"] = Field(
        "gemini",
        description="Origin source: 'gemini' for live AI generation, or 'offline_bank' for offline fallback."
    )
    is_fallback: bool = Field(
        False,
        description="Flag indicating if served from offline bank. Never disguised as AI."
    )
    id: Optional[str] = Field(None, description="Unique question identifier if assigned.")


class QuizGradingResult(BaseModel):
    """Result of grading a single quiz question answer deterministically."""
    is_correct: bool
    score: float
    correct_index: int
    selected_index: int
    explanation: str


class QuizBatchGradingResult(BaseModel):
    """Result of grading an entire quiz submission deterministically."""
    total_questions: int
    correct_count: int
    score_percentage: float
    results: List[QuizGradingResult]


