class ProjectItemSchema(BaseModel):
    """Structured project record extracted from resume text."""
    name: str = Field(..., min_length=2, description="Project name or title.")
    tech_stack: List[str] = Field(default_factory=list, description="Technologies, libraries, or tools used.")
    description: str = Field(default="", description="Summary of project achievements and architecture.")


class ResumeAnalysisSchema(BaseModel):
    """Structured resume profile extracted via Gemini Pro or deterministic parser."""
    skills: List[str] = Field(default_factory=list, description="Extracted technical and professional skills.")
    projects: List[Dict[str, Any]] = Field(
        default_factory=list,
        description="List of project dicts, e.g. [{'name': '...', 'tech_stack': [...], 'description': '...'}]"
    )
    experience: List[str] = Field(
        default_factory=list,
        description="List of work experience entries, companies, and roles."
    )
    education: List[str] = Field(
        default_factory=list,
        description="Degrees, academic institutions, or certifications."
    )
    gaps: List[str] = Field(
        default_factory=list,
        description="Identified resume gaps, lack of metrics, or areas for interview elaboration."
    )


class ResumeQuestionSchema(BaseModel):
    """Interview question strictly grounded in candidate resume projects or experience."""
    question: str = Field(..., min_length=10, description="The interview question text.")
    referenced_item: str = Field(
        ...,
        min_length=2,
        description="Project, role, or company explicitly referenced from the resume."
    )
    intent: str = Field(..., description="Core competency, technical depth, or STAR element assessed.")
    difficulty: Literal["easy", "medium", "hard"] = Field(
        "medium",
        description="Difficulty tier: 'easy' | 'medium' | 'hard'"
    )

    @field_validator("difficulty", mode="before")
    @classmethod
    def normalize_difficulty(cls, v: Any) -> str:
        if isinstance(v, str):
            clean = v.strip().lower()
            if clean in ("easy", "medium", "hard"):
                return clean
        return "medium"


class LabeledResumeQuestion(ResumeQuestionSchema):
    """Resume question labeled with origin provenance and fallback status."""
    source: Literal["gemini", "offline_bank"] = Field(
        "gemini",
        description="Origin source: 'gemini' for live AI generation, or 'offline_bank' for offline fallback."
    )
    is_fallback: bool = Field(
        False,
        description="Flag indicating if served from offline bank. Never disguised as AI."
    )


# =====================================================================
# RUBRIC & EVALUATION SCHEMAS
# =====================================================================

class CriterionEvaluationSchema(BaseModel):
    """Evaluation of an individual rubric criterion with score and 1-sentence justification."""
    criterion_name: str = Field(..., min_length=2, description="Criterion name, e.g. 'Technical Accuracy'.")
    score: float = Field(..., ge=0.0, le=100.0, description="Criterion score between 0.0 and 100.0.")
    max_score: float = Field(100.0, description="Maximum possible score (default 100.0).")
    justification: str = Field(..., min_length=5, description="Exactly one concise justification sentence.")

    @field_validator("score", mode="before")
    @classmethod
    def clamp_score(cls, v: Any) -> float:
        val = float(v)
        return max(0.0, min(100.0, val))

    @field_validator("justification")
    @classmethod
    def validate_single_sentence(cls, v: str) -> str:
        clean = (v or "").strip()
        if not clean:
            raise ValueError("Justification cannot be empty")
        # Ensure concise single sentence ending in punctuation
        sentences = [s.strip() for s in re.split(r'(?<=[.?!])\s+', clean) if s.strip()]
        if len(sentences) > 1:
            clean = sentences[0]
        if not clean.endswith((".", "!", "?")):
            clean += "."
        return clean


class AnswerEvaluationSchema(BaseModel):
    """Structured evaluation of an answer across all criteria."""
    criteria: List[CriterionEvaluationSchema] = Field(..., min_length=1, description="List of evaluated criteria.")
    strengths: List[str] = Field(default_factory=list, description="Demonstrated candidate strengths.")
    improvements: List[str] = Field(default_factory=list, description="Targeted recommendations for improvement.")
    source: Literal["gemini", "offline_bank"] = Field("gemini", description="Provenance of evaluation.")
    is_fallback: bool = Field(False, description="Flag indicating if generated via offline fallback heuristics.")
    computed_score: Optional[float] = Field(None, description="Score computed deterministically by Python rubric code.")


class EvaluationReportSchema(BaseModel):
    """Final aggregate evaluation report with deterministically computed scores and performance tier."""
    round_scores: Dict[str, float] = Field(..., description="Deterministic scores for each evaluation round or category.")
    overall_score: float = Field(..., ge=0.0, le=100.0, description="Final deterministic weighted aggregate score.")
    tier: Literal["Strong Hire", "Hire", "Borderline", "Needs Improvement"] = Field(
        ...,
        description="Performance tier classified deterministically from overall_score."
    )
    feedback_summary: str = Field(..., min_length=10, description="Executive performance summary.")
    improvement_plan: List[str] = Field(default_factory=list, description="Structured roadmap for candidate development.")



